<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$labels=['PENDING'=>'Chờ xác nhận','CONFIRMED'=>'Đã xác nhận','PROCESSING'=>'Đang xử lý','SHIPPING'=>'Đang giao','DELIVERED'=>'Đã giao','CANCELLED'=>'Đã hủy','RETURNED'=>'Đã trả hàng']; ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tra cứu đơn</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 text-slate-100"><main class="mx-auto max-w-3xl p-5 pt-10"><a class="text-blue-300" href="?page=home">← Cửa hàng</a><h1 class="my-5 text-3xl font-bold">Tra cứu đơn hàng</h1><form class="grid gap-3 rounded-xl bg-slate-900 p-5 sm:grid-cols-2"><input type="hidden" name="page" value="track-orders"><label>Mã đơn<input required name="code" value="<?= $e($_GET['code']??'') ?>" class="mt-1 w-full rounded bg-slate-800 p-3"></label><label>Số điện thoại nhận hàng<input required name="phone" value="<?= $e($_GET['phone']??'') ?>" class="mt-1 w-full rounded bg-slate-800 p-3"></label><button class="rounded bg-blue-600 p-3 sm:col-span-2">Tra cứu</button></form><?php if($error): ?><p class="mt-4 rounded bg-red-900 p-3"><?= $e($error) ?></p><?php endif ?><?php if(isset($_GET['code'])&&$order===null): ?><p class="mt-4">Không tìm thấy đơn hàng phù hợp.</p><?php endif ?><?php if($order): ?><article class="mt-5 rounded-xl bg-slate-900 p-5"><h2 class="text-xl font-bold"><?= $e($order['order_code']) ?></h2><p class="my-2">Trạng thái: <b><?= $e($labels[$order['order_status']]??$order['order_status']) ?></b></p><ol class="my-4 flex flex-wrap gap-2"><?php foreach(['PENDING','CONFIRMED','PROCESSING','SHIPPING','DELIVERED'] as $s): ?><li class="rounded px-3 py-2 <?= $order['order_status']===$s?'bg-blue-700':'bg-slate-800' ?>"><?= $e($labels[$s]) ?></li><?php endforeach ?></ol><?php foreach($order['items'] as $i): ?><p><?= $e($i['product_name']) ?> · <?= $e($i['variant_name']) ?> × <?= (int)$i['quantity'] ?></p><?php endforeach ?><p class="mt-3">Tổng: <?= number_format((float)$order['total_amount'],0,',','.') ?> ₫</p></article><?php endif ?></main></body></html>
